style.css:
@-moz-document domain("classroom.google.com") {
/* Main Background */
    body, .zQTmif, .g3VIld, .JwQpJ {
        background-color: #ffe6f2 !important;
    }

    /* Headers & Navigation */
    .YVvGBb, .oBSRLe, .aP4mo, .gb_vd, .gb_Wd {
        background-color: #ffb6c1 !important;
        color: #7a3b56 !important;
    }

    /* Cards & Containers */
    .gHz6xd, .ITp7Ee, .onkcG, .I3EnF, .zWGUib {
        background-color: #ffccd5 !important;
        color: #7a3b56 !important;
    }

    /* Text Colors */
    .onkcG, .iymv3b, .zHQkBf {
        color: #7a3b56 !important;
    }

    /* Buttons */
    .VfPpkd-LgbsSe, .VfPpkd-LgbsSe-OWXEXe-INsAgc, .VfPpkd-Bz112c-LgbsSe {
        background-color: #ffb6c1 !important;
        color: #fff !important;
        border-color: #ff9eb5 !important;
    }

    /* Dropdown Menus */
    .VfPpkd-StrnGf-rymPhb {
        background-color: #ffb6c1 !important;
        color: #7a3b56 !important;
    }

    /* Hover Effects */
    .onkcG:hover, .iymv3b:hover, .VfPpkd-LgbsSe:hover, .VfPpkd-StrnGf-rymPhb:hover {
        background-color: #ff9eb5 !important;
    }

    /* Borders */
    .VfPpkd-StrnGf-rymPhb, .gHz6xd, .ITp7Ee, .JwQpJ {
        border-color: #ff9eb5 !important;
    }
}
